-- The two checklists published on 2026-10-10: a day when pain or illness
-- sets the terms (Body) and an apology you owe (Communication).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-10`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('a-day-when-your-body-hurts', 'A Day When Your Body Hurts', 'For the days pain or illness sets the terms and the plans have to shrink. It helps you cut the day down to what matters, ask for the help you would rather not ask for, and get through it without adding guilt to the pile.', 'Body', '["Pick the one thing that has to happen today — the rest of the list can wait a day.", "Cancel or move one thing before noon — canceling early costs less than canceling late.", "Ask one person for one specific thing — people help better when the ask is small and clear.", "Set your medication and water within reach — the trip across the room is the part that stops you.", "Put something on that needs nothing from you — easy company beats an empty room.", "Change position or get outside for five minutes — a small change is not the same as pushing through.", "Write down what today was like for your next visit — the detail is gone by the time you are asked.", "Drop the ledger of what you did not do — a hard day is not a debt you owe."]'::jsonb, 'as needed', array['Body', 'Self-Compassion']::text[], 1, '2026-10-10T16:00:00+00:00'::timestamptz),
  ('when-you-owe-someone-an-apology', 'When You Owe Someone an Apology', 'For when you know you were in the wrong and the longer you leave it the worse it gets. It helps you work out what to say, say it without a defense attached, and then let the other person decide what happens next.', 'Communication', '["Write down the specific thing you did — a vague apology lands as no apology.", "Cut every sentence starting with because — the explanation turns it back into your story.", "Say what it cost them, not what you meant — intent is the part they already know.", "Name one thing you will do differently — an apology without a change is just regret out loud.", "Do it today, in the way they prefer — waiting adds a second thing to apologize for.", "Ask nothing of them in the same breath — forgiveness is not yours to schedule.", "Sit with the silence afterward — their reaction is theirs, and it may take a while.", "Stop retelling it to yourself tonight — shame keeps you busy instead of changed."]'::jsonb, 'as needed', array['Communication', 'Shame']::text[], 1, '2026-10-10T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
